def is_pairwise_coprime(arr):
    from math import gcd
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if gcd(arr[i], arr[j]) != 1:
                return False
    return True

def get_S_values(limit):
    S_set = set()
    # Case k=3, x=1
    for y in range(2, limit):
        for z in range(y + 1, limit):
            if y * z > limit * limit: break
            from math import gcd
            if gcd(y, z) == 1:
                S_set.add(y * z)

    # Case k=3, x, y, z > 1
    for x in range(2, limit):
        for y in range(x + 1, limit):
            for z in range(y + 1, limit):
                if x * y * z > limit * limit: break
                from math import gcd
                if gcd(x, y) == 1 and gcd(y, z) == 1 and gcd(x, z) == 1:
                    S_set.add(x * y * z)
    return sorted(list(S_set))

print(get_S_values(100)[:25])
